import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/tes2')
from h import *
X=[]
X.append(r(9632103,"Galletas veganas saludables de avena","Masticables, ligeramente dulces e increíblemente deliciosas, estas galletas veganas saludables de avena son FÁCILES de preparar, con solo 5 ingredientes y ¡apenas 20 minutos!","10 galletas","1 porción",
["2 tazas de avena en hojuelas, sin gluten si lo prefiere","1 cucharadita de canela","1 cucharadita de polvo para hornear","½ taza de puré de manzana sin azúcar","¼ de taza de jarabe de arce u otro endulzante líquido de su elección","¼ de taza de chispas de chocolate veganas o pasas, opcional"],
["Forre una bandeja para hornear con papel pergamino y precaliente el horno a 350 grados F.","Agregue la avena a un procesador de alimentos y procese suavemente hasta que la avena esté finamente picada, con algunas partes como harina, pero sin procesar de más hasta convertirla en harina.","Pase la avena a un tazón para mezclar y agregue todos los demás ingredientes, excepto el complemento opcional. Mezcle bien para distribuir de manera uniforme. Ahora agregue el complemento de su elección, si lo usa, y mezcle bien.","Divida la masa en 10 galletas, forme una bola con las manos (use las manos húmedas para evitar que se pegue) y luego colóquela sobre la bandeja para hornear. Ahora, con el reverso de una cuchara, presione suavemente cada galleta y dé forma redondeada a los lados, si es necesario.","Hornee de 10 a 12 minutos y retire del horno. (Se verán poco cocidas.) Déjelas enfriar por lo menos 5 minutos y luego páselas a una rejilla para que se enfríen otros 5-10 minutos y las galletas terminen de firmarse y endurecerse. ¡Disfrute!"],
["No procese demasiado la avena. No queremos hacer harina, o esto alterará la textura de sus galletas de avena. Use las manos húmedas para dar forma a la masa de las galletas en bolitas. Esto ayudará a evitar que se peguen a las manos y facilitará enrollarlas. Cuando presione las galletas, hágalo suavemente para evitar romperlas. Use la otra mano para ayudar a dar forma redondeada a los bordes si no se sostienen bien. No use más de ¼ de taza de complementos, ya sean chispas de chocolate, pasas u otro complemento. Demasiado de cualquier complemento hará que les cueste más mantenerse unidas. No hornee de más las galletas. Para galletas de avena masticables, deben quedar ligeramente poco horneadas. Pueden parecer poco cocidas, pero asegúrese de no hornear de más para evitar que se resequen. Los bordes estarán más firmes y el centro estará suave. Déjelas reposar a temperatura ambiente por lo menos 5-10 minutos después de hornear. Este breve período de enfriamiento endurecerá las galletas y les permitirá firmarse por completo. Las galletas se conservan de 2 a 3 días refrigeradas, hasta por 1 semana en el refrigerador, o congélelas hasta por 3 meses."],[]))
X.append(r(9633263,"Galletas veganas saludables de camote","¡Galletas veganas de camote (batata) suaves, masticables, endulzadas naturalmente e increíblemente deliciosas!","12 galletas","1 galleta",
["1.25 tazas de camote (batata) machacado, de aprox. 1 camote grande (2.5 tazas en cubos)","½ taza de plátano (banana) machacado, de aprox. 2 plátanos medianos (use plátanos MADUROS)","70 gramos de harina de avena, aprox. ½ taza + 2 cucharadas, use sin gluten si lo prefiere","50 gramos de harina de arroz integral, aprox. ¼ de taza (o use más harina de avena)","70 gramos de avena en hojuelas, aprox. ½ taza + 2 cucharadas","1 cucharada de jarabe de arce, opcional","1 cucharadita de canela, opcional"],
["Precaliente el horno a 375℉/190℃ y forre una bandeja grande para hornear con papel pergamino.","Pele y corte en cubos los camotes, colóquelos en una cacerola u olla y cúbralos con agua. Lleve a ebullición y cocine hasta que estén blandos, aprox. 8-10 minutos. Escurra y devuelva a la cacerola. Luego macháquelos bien con un machacador de papas.","Agregue todos los demás ingredientes a la cacerola con el camote machacado y mezcle bien. La masa será espesa.","Use una cuchara para galletas para formar las bolitas de masa y colóquelas en la bandeja para hornear. Luego, presione suavemente cada una con un tenedor para aplanarlas y darles forma. Hornee las galletas de camote de 15 a 18 minutos, hasta que estén doradas.","Retire del horno, deje enfriar durante 5 minutos y disfrute."],
["Use plátanos muy maduros, con la cáscara manchada de marrón. Como estas galletas están endulzadas naturalmente, conviene usar plátanos muy maduros y dulces.","Si es posible, use una báscula para pesar los ingredientes y obtener los mejores resultados. Si no tiene una báscula de cocina, ponga la harina con una cuchara en la taza medidora y nivele. No la tome con la taza directamente de la bolsa, o podría terminar con demasiada.","Si no tiene harina de avena o de arroz integral, puede usar harina integral de trigo todo uso con resultados similares. Use 110 g (aprox. ¾ de taza) solo si no evita el gluten.","Puede preparar harina de arroz integral y harina de avena si no tiene a mano. Yo muelo los ingredientes en mi Vitamix.","Las sobras se conservan en un recipiente sellado a temperatura ambiente de 1 a 2 días, refrigeradas de 3 a 4 días, o congeladas en un recipiente hermético hasta por 3 meses."],[]))
X.append(r(9635144,"Totopos veganos","Los totopos veganos caseros están listos en un santiamén y no necesitan aceite. Son el bocadillo crujiente perfecto cuando le dan antojo de totopos, sin ninguna culpa.","4 porciones","1 porción",
["8 tortillas de maíz de seis pulgadas","2 cucharadas de jugo de limón, aprox. 1 limón grande","½ cucharadita de sal marina","¼ de cucharadita de ajo en polvo, opcional"],
["Precaliente el horno a 400 grados F (205 grados C) y forre dos bandejas grandes para hornear con papel pergamino.","Apile las tortillas de maíz de manera uniforme sobre una tabla de cortar. Luego use un cortador de pizza para cortarlas en cuatro partes. (Si usa tortillas más grandes, córtelas en seis piezas.)","Distribuya los totopos cortados en una capa uniforme sobre las bandejas para hornear. Luego unte cada uno con jugo de limón y espolvoree de manera uniforme con sal y ajo en polvo, si lo usa.","Hornee de 8 a 10 minutos, revisando con frecuencia hacia el final de la cocción. Debe quedar dorado y crujiente, pero no demasiado cocido."],
["Uso tortillas de maíz de seis pulgadas y corto cada una en cuatro partes para hacer totopos del tamaño perfecto, estilo restaurante. Si usa tortillas más grandes, puede cortarlas en seis piezas. Revise los totopos con frecuencia hacia el final de la cocción. Los totopos pasarán rápidamente de estar perfectos a estar demasiado cocidos, así que use el temporizador del horno para programar recordatorios."],[]))
X.append(r(9635628,"Donas veganas horneadas con glaseado","¡Donas veganas con glaseado dulces, húmedas e increíblemente deliciosas, horneadas (no fritas) para un antojo máximo!","12 donas","1 porción",
[("Ingredientes secos","240 gramos de harina integral para repostería, aprox. 2 tazas"),("Ingredientes secos","2 cucharaditas de polvo para hornear"),("Ingredientes secos","1 cucharadita de canela"),("Ingredientes húmedos","½ taza de puré de manzana sin azúcar"),("Ingredientes húmedos","½ taza de jarabe de arce"),("Ingredientes húmedos","½ taza de leche de soya u otra leche no láctea"),("Ingredientes húmedos","2 cucharaditas de extracto puro de vainilla"),("Para el glaseado","¾ de taza de azúcar glas"),("Para el glaseado","2 cucharaditas de jugo de limón"),("Para el glaseado","1-2 cucharadas de leche de soya u otra leche sin lácteos")],
["Precaliente el horno a 350℉/176℃ y prepare suficientes moldes para donas para hacer 12 donas. (Yo uso 2 moldes de 6 donas cada uno.)","Bata juntos la harina, el polvo para hornear y la canela en un tazón mediano para mezclar. Luego agregue los ingredientes húmedos y revuelva hasta combinar.","Divida la masa de las donas entre los 12 moldes y hornee de 12 a 15 minutos. Las donas están listas cuando están firmes al tacto, pero ceden un poco al presionarlas suavemente. Retire del horno y déjelas enfriar antes de glasearlas.","Mientras las donas se enfrían, prepare el glaseado. Combine el azúcar, el jugo de limón y la leche (empezando con 1 cucharada) en un tazón pequeño. Agregue un poco más de leche si es necesario.","Una vez frías, sumerja la parte superior de cada dona en el glaseado y colóquelas con el glaseado hacia arriba sobre una rejilla para que el glaseado se endurezca. ¡Disfrute!"],
["Pese la harina con una báscula de cocina para obtener los resultados más exactos. Tomar la harina con la taza directamente de la bolsa puede hacer que se use demasiada harina y alterar la textura.","Use polvo para hornear fresco y activo. Una vez abierto, el polvo para hornear empieza a perder su efectividad, por lo que es mejor consumirlo dentro de los 6 meses.","Deje enfriar las donas de 10 a 15 minutos antes de intentar sacarlas del molde. Si las donas están demasiado calientes, corre el riesgo de romperlas.","Una vez pasadas a una rejilla, deje que sigan enfriándose a temperatura ambiente antes de glasearlas.","La información nutricional anterior incluye 1 dona, con el glaseado."],[]))
X.append(r(9644787,"Pan vegano de arándano rojo y naranja con glaseado dulce de naranja","Un pan vegano saludable de arándano rojo y naranja, húmedo, endulzado naturalmente y hecho con ingredientes saludables","12 rebanadas (1 molde para pan de 5\"x9\")","1 porción",
[("Ingredientes secos","2 tazas de harina de avena, sin gluten si lo prefiere"),("Ingredientes secos","2.5 cucharaditas de polvo para hornear"),("Ingredientes secos","½ cucharadita de bicarbonato de sodio"),("Ingredientes secos","1 cucharadita de canela"),("Ingredientes húmedos","1 taza de dátiles sin hueso"),("Ingredientes húmedos","1.5 tazas de agua"),("Ingredientes húmedos","½ taza (más 2 cucharadas para el glaseado, reservadas) de jugo de naranja recién exprimido de aprox. 1 naranja grande"),("Ingredientes húmedos","1 cucharada de ralladura de naranja"),("Ingredientes húmedos","⅓ de taza de puré de manzana sin azúcar"),("Ingredientes húmedos","1 taza de arándanos rojos frescos o arándanos azules frescos si no hay arándanos rojos frescos donde usted vive")],
["Precaliente el horno a 350 grados F y forre un molde para pan de 9\" x 5\" (o similar) con papel pergamino.","En un tazón grande para mezclar, combine todos los ingredientes secos y bata juntos. Reserve.","Agregue los dátiles sin hueso y el agua a una licuadora y procese hasta que quede completamente suave. Esto rendirá aproximadamente 2 tazas de jarabe de dátil. Mida 1.5 tazas, que se usarán en el pan, y la 1/2 taza restante se usará después para el glaseado. No use más de 1.5 tazas en el pan.","Ahora agregue los ingredientes húmedos (excepto los arándanos rojos) al tazón de ingredientes secos: 1.5 tazas del jarabe de dátil que preparó, 1/2 taza de jugo de naranja, la ralladura de naranja y el puré de manzana. Mezcle hasta combinar y luego incorpore con movimientos envolventes los arándanos rojos.","Vierta la masa en el molde preparado y golpee suavemente el molde 2-3 veces sobre una superficie dura para asegurarse de que no haya espacios en el pan. No presione con una espátula.","Hornee en el horno precalentado de 45 a 55 minutos, hasta que un palillo insertado en el centro salga seco. Según su horno y el tamaño del molde, el tiempo de cocción variará. Una vez horneado, retire del horno y deje enfriar durante 10 minutos antes de sacar el pan del molde. Pase a una rejilla para que se enfríe por completo antes de glasear.","Para preparar el glaseado: Agregue 2 cucharadas de jugo de naranja recién exprimido a la 1/2 taza restante de jarabe de dátil y mezcle bien. Luego rocíe el glaseado sobre el pan ya frío. ¡Corte en rebanadas y disfrute!"],
["Si no tiene una licuadora potente, remoje los dátiles en agua tibia durante unos 15 minutos primero. Luego escúrralos y prepare el jarabe de dátil según las indicaciones. Esto ayudará a ablandar los dátiles, haciéndolos más fáciles de licuar. Use polvo para hornear fresco y activo. El polvo para hornear que lleva abierto en su despensa más de 6 meses puede empezar a perder su efectividad. Asegúrese de que su pan de arándano rojo y naranja esté completamente frío antes de glasearlo. Si no tiene arándanos rojos frescos donde vive, los arándanos azules frescos también quedan muy bien en este pan dulce. El pan se conserva cubierto a temperatura ambiente de 2 a 3 días, o congélelo en un recipiente hermético de 3 a 4 semanas."],[]))
X.append(r(9652525,"Macarrones veganos con queso y aguacate","¡Un plato rico y cremoso que gusta tanto a niños como a adultos! Estos macarrones de aguacate son fáciles de preparar, saludables sin que se note y maravillosamente deliciosos.","6 porciones","1 porción",
["¼ de taza de nueces de la India (anacardos) crudas","1 aguacate grande maduro, pelado y sin hueso","1.5 tazas de leche de nuez de la India (anacardo) sin azúcar o la leche vegetal de su elección","3 cucharadas de jugo de limón, aprox. 1 limón pequeño o la mitad de uno grande","¼ de taza de levadura nutricional","1.5 cucharaditas de sal marina","1 cucharadita de ajo en polvo","1 cucharadita de pimentón ahumado","1 cucharada de mantequilla vegana o aceite de aguacate, opcional","450 gramos de pasta de macarrones, sin gluten si lo prefiere",("Decoraciones opcionales","queso parmesano vegano, muy recomendado"),("Decoraciones opcionales","rodajas de aguacate"),("Decoraciones opcionales","perejil, cebollino o eneldo fresco")],
["Lleve a ebullición una olla grande con agua con sal y cocine la pasta según las instrucciones del paquete para pasta al dente. Escurra y devuelva a la olla.","Mientras tanto, agregue todos los ingredientes (excepto la pasta) a una licuadora de alta velocidad y procese hasta que quede suave. Vierta la salsa sobre la pasta y mezcle bien.","Sirva con la decoración de su elección y disfrute."],
["Si no tiene una licuadora de alta velocidad, asegúrese de remojar primero las nueces de la India. Remoje en agua hirviendo durante 30 minutos, luego escurra y use según las indicaciones. Ponga sal al agua de cocción de la pasta para obtener los mejores resultados. No cocine de más la pasta. Cocine según las instrucciones del paquete para al dente. La pasta sabe mejor con un poco de firmeza, y no demasiado blanda. Las sobras se conservan refrigeradas de 2 a 3 días. Para recalentar, agregue un poco de leche vegetal, agua o caldo a una sartén con la pasta, para humedecerla de nuevo y calentarla por completo."],[]))
X.append(r(9655561,"Tarta vegana de arándanos azules [¡más saludable que la mayoría!]","Esta tarta vegana de arándanos azules es fresca y dulce con un toque ácido. Una versión más saludable de la tarta tradicional, con menos azúcar, sin aceite ni mantequilla, ¡y con masa integral!","8 porciones","1 porción",
["2 masas de tarta veganas sin aceite o la masa de tarta de su elección","5.5 tazas de arándanos azules","⅓ de taza de azúcar de coco sin refinar o azúcar granulada de su elección","¼ de taza de maicena o harina de tapioca","2 cucharadas de jugo de limón, aprox. 1 limón mediano","1 cucharadita de canela, opcional pero recomendada","1-2 cucharadas de leche de nuez de la India (anacardo) sin azúcar o la leche vegetal de su elección","1-2 cucharadas de azúcar blanca, opcional, para espolvorear"],
["Prepare la masa de tarta de su elección y hornéela en blanco según sus instrucciones. Si usa mi masa de tarta sin aceite, hornee 1 masa durante 15 minutos, hasta que los bordes estén dorados. Luego retire del horno y reserve. La segunda masa de tarta extiéndala y resérvela para colocarla encima de la tarta, una vez rellena.","Precaliente el horno a 350 grados F.","En un tazón para mezclar, combine los arándanos azules, el azúcar, la maicena, el jugo de limón y la canela. Mezcle bien. Luego vierta la mezcla en la masa de tarta preparada.","Ahora use la segunda masa de tarta para cubrir el relleno. Puede colocar la masa entera encima y sellar los bordes, haciendo orificios de ventilación en el centro de la masa. Como alternativa, puede hacer un patrón de tejido de canasta o recortes en forma de estrella (o de cualquier forma) para cubrir la tarta. Usted decide.","Unte un poco de la leche vegetal de su elección sobre la masa superior y, si lo desea, puede espolvorear con azúcar.","Hornee la tarta de 45 a 55 minutos, hasta que los jugos de los arándanos azules burbujeen y la masa esté dorada. Si su tarta se cocina demasiado rápido, cubra la parte superior con un protector de tarta o papel de aluminio para evitar que se oscurezca demasiado.","Retire del horno y deje enfriar por completo antes de cortar y servir. La tarta debe enfriarse para firmarse por completo."],
["Si su masa se cocina demasiado rápido, cúbrala con un protector de tarta o papel de aluminio para evitar que la masa se cocine de más. ¡Asegúrese de hacer orificios de ventilación si usa una masa de tarta completa para la parte superior! Si hace un patrón de tejido de canasta o usa los recortes en forma de estrella, no son necesarios los orificios. ¡Deje que la tarta de arándanos azules se enfríe por completo antes de cortarla! El tiempo de enfriamiento es crucial para que la tarta se firme bien. Aunque PUEDE cortarla caliente, estará líquida hasta que se enfríe. Las sobras se pueden refrigerar de 3 a 4 días, o sellarlas herméticamente y congelarlas hasta por 2 meses. La información nutricional incluye 2 masas de tarta completas sin aceite. Si usa otra masa, omite la masa superior o usa recortes en forma de estrella, la información nutricional variará."],[]))
X.append(r(9659242,"Tarta vegana de nuez pecana más saludable [sin jarabe de maíz]","Una tarta vegana de nuez pecana más saludable, increíblemente deliciosa, rica, dulce, con sabor a caramelo, cargada de nueces pecanas y el postre navideño perfecto.","8 porciones","1 porción",
[("Para la masa (o masa de tarta vegana","90 gramos (aprox. ¾ de taza) de harina de almendra"),("Para la masa (o masa de tarta vegana","80 gramos (aprox. ¾ de taza) de harina integral blanca de trigo, también conocida como harina integral suave o harina integral para repostería"),("Para la masa (o masa de tarta vegana","1 aguacate mediano maduro"),("Para la masa (o masa de tarta vegana","¼ de cucharadita de sal marina"),("Para la masa (o masa de tarta vegana","4 cucharadas de leche de almendras o la leche no láctea de su elección"),("Para la masa (o masa de tarta vegana","1-2 cucharadas de agua, ¡SOLO si es necesario!"),("Para la masa (o masa de tarta vegana","2 cucharadas de azúcar de coco o azúcar granulada de su elección, opcional"),("Para la masa (o masa de tarta vegana","1 cucharadita de canela, opcional"),("Para el relleno","1 ¼ tazas de mitades de nuez pecana"),("Para el relleno","⅔ de taza de jarabe de arce"),("Para el relleno","3 cucharadas de melaza de primera calidad (fancy)"),("Para el relleno","¼ de taza de linaza molida"),("Para el relleno","⅓ de taza de leche de nuez de la India (anacardo) sin azúcar o la leche de su elección"),("Para el relleno","3 cucharadas de almidón de tapioca"),("Para el relleno","2 cucharadas de mantequilla de nuez de la India o de almendras"),("Para el relleno","½ cucharadita de sal marina"),("Complementos opcionales para el relleno","2.5 cucharaditas de café instantáneo granulado"),("Complementos opcionales para el relleno","1 cucharadita de extracto puro de vainilla"),("Complementos opcionales para el relleno","1 cucharadita de canela")],
["Prepare la masa de tarta de su elección y reserve. Yo uso mi masa de tarta sin aceite (vea la publicación para instrucciones detalladas y fotos paso a paso de cómo hacer la masa) con la opción de harina de almendra, que recomiendo mucho. Si usa esta masa, no es necesario hornearla previamente (hornear en blanco).","Precaliente el horno a 325 grados F.","Agregue todos los ingredientes del relleno, excepto las nueces pecanas, a un tazón para mezclar y bata bien hasta combinar. Luego agregue las mitades de nuez pecana y revuelva rápidamente para cubrirlas.","Vierta la mezcla en la masa preparada y hornee durante 15 minutos. Luego coloque un protector de tarta sobre la tarta o cúbrala sin apretar con papel de aluminio y hornee otros 25 minutos. (Tiempo total de horneado: 40 minutos.) Esto evitará que la masa se cocine demasiado rápido y se oscurezca demasiado.","Retire del horno y deje enfriar sobre una rejilla durante un mínimo de dos horas antes de cortar."],
["Deje que la tarta de nuez pecana se enfríe a temperatura ambiente un mínimo de dos horas después de hornear. Este tiempo de enfriamiento es esencial para que la tarta se firme y facilite el corte. Asegúrese de que la tarta esté completamente fría a temperatura ambiente antes de refrigerarla o congelarla. Puede preparar la tarta con anticipación, pero sabe mejor los días 1-2. Las sobras se conservan refrigeradas de 3 a 5 días, o congélelas hasta por 2 meses."],[]))
X.append(r(9660382,"Magdalenas veganas de frittata [magdalenas veganas saladas]","Estas magdalenas veganas de frittata, también conocidas como magdalenas veganas saladas, son la alternativa definitiva a los tradicionales moldes de huevo, que deleitarán su paladar y le darán un gran comienzo del día.","12 magdalenas","1 porción",
["¼ de taza de cebolla amarilla picada finamente","½ taza de pimiento rojo picado en cubos, aprox. 1 pimiento pequeño","1 taza de champiñones cremini o baby bella picados en cubos, aprox. 4-5 champiñones","¾ de taza de brócoli picado finamente, aprox. 3-5 floretes","300 gramos de harina de garbanzo, aprox. 2 tazas","4 cucharadas de levadura nutricional","1 cucharadita de ajo en polvo","½ cucharadita de cúrcuma, para dar color","1 cucharadita de sal marina o sustituya la mitad por sal negra, también conocida como kala namak","¼ de cucharadita de pimienta negra, opcional pero recomendada","1 cucharadita de polvo para hornear","2.5 tazas de agua"],
["Precaliente el horno a 400℉/204℃ y prepare un molde antiadherente para magdalenas o engráselo si es necesario.","Coloque todas las verduras picadas en una sartén y espolvoréelas con un poco de sal y pimienta, si lo desea. Saltee en seco, revolviendo con frecuencia, hasta que se reduzcan y ablanden, aprox. 5 minutos. Reserve.","Mientras tanto, en un tazón grande, agregue la harina de garbanzo, la levadura nutricional, los condimentos y el polvo para hornear, y bata para combinar. Luego vierta el agua y mezcle bien.","Divida las verduras salteadas entre los 12 moldes para magdalenas, aproximadamente 1 cucharada colmada por magdalena. Luego vierta la masa de garbanzo encima para distribuirla de manera uniforme entre las 12 magdalenas. Use una cuchara para revolver suavemente cada magdalena, para distribuir de manera uniforme las verduras y la masa. (NO OMITA MEZCLAR.)","Hornee durante 30 minutos o hasta que un palillo insertado en el centro salga limpio. Retire del horno y deje enfriar por lo menos 10 minutos. Luego retírelas con cuidado del molde."],
["Revuelva las magdalenas ANTES de hornear. Esto asegurará una distribución uniforme de las verduras. Además, asegúrese de que algo de masa llegue al fondo de los moldes para que las magdalenas tengan una forma uniforme y para evitar que se peguen.","Como alternativa, puede verter una cucharada de masa de garbanzo en el fondo de cada molde para magdalenas, seguida de las verduras, y luego verter el resto de la masa encima.","Deje reposar las magdalenas a temperatura ambiente por lo menos 10 minutos antes de sacarlas del molde. Este período de enfriamiento ayuda a que las magdalenas se firmen para que no se rompan al sacarlas.","Si evita el aceite y no desea engrasar el molde para magdalenas, deje que las magdalenas se enfríen un poco más antes de intentar sacarlas. Luego use un cuchillo de mesa para deslizarlo suavemente alrededor de cada magdalena si están un poco pegadas, y sáquelas con una cuchara.","Las sobras se conservan en un recipiente sellado en el refrigerador hasta por 5 días. O congélelas hasta por 3 meses. Asegúrese de enfriar por completo las magdalenas veganas de huevo antes de refrigerarlas o congelarlas. Puede recalentar los moldes de huevo en el microondas o en un horno tostador, o disfrutarlos fríos."],[]))
X.append(r(9660403,"Jamón vegano [jamón de seitán]","¡Jamón vegano con textura de carne, tierno e increíblemente sabroso, cubierto con un glaseado ahumado de arce!","8 porciones","1 porción",
[("Para el jamón","1 taza de garbanzos enlatados o cocidos (escurridos)"),("Para el jamón","1 taza de caldo de verduras; use un caldo salado/sabroso como mi versión casera"),("Para el jamón","3-4 dientes de ajo"),("Para el jamón","3 cucharadas de pasta de tomate"),("Para el jamón","2 cucharadas de aceite de aguacate o el aceite de cocina de su elección (sustituya por más caldo para una versión sin aceite)"),("Para el jamón","2 cucharaditas de humo líquido"),("Para el jamón","1.5 cucharadas de pimentón ahumado"),("Para el jamón","1 cucharadita de sal marina"),("Para el jamón","¼ de cucharadita de canela"),("Para el jamón","¼ de cucharadita de clavo molido"),("Para el jamón","210 gramos de gluten de trigo vital, aprox. 1.75 tazas"),("Para el glaseado de arce","½ taza de caldo de verduras; use un caldo salado/sabroso como mi versión casera"),("Para el glaseado de arce","3 cucharadas de jarabe de arce"),("Para el glaseado de arce","2 cucharaditas de pimentón ahumado"),("Para el glaseado de arce","1 cucharadita de mostaza amarilla")],
["Agregue todos los ingredientes del jamón EXCEPTO el gluten de trigo vital a un procesador de alimentos y procese hasta que esté casi mezclado. Luego agregue la MITAD del gluten de trigo vital y continúe procesando hasta que se integre. Ahora agregue la otra mitad restante y procese hasta que esté casi combinado.","Pase la mezcla a una superficie limpia y amase a mano de 1 a 2 minutos, retorciendo y anudando la mezcla mientras lo hace. Luego forme un óvalo, lo más uniforme que pueda, pero no tiene que ser perfecto. (Vea las fotos del proceso arriba para una referencia visual.)","Envuelva bien el asado con una gasa de queso (o con papel pergamino y papel de aluminio) y asegure los extremos.","Agregue 1.5 tazas de agua al fondo de su Instant Pot y coloque dentro el trébede (rejilla). Luego coloque el jamón envuelto encima del trébede. Cierre la tapa y asegúrese de que la válvula esté en la posición de sellado. Programe la función de vapor durante 40 minutos y deje que la presión se libere de forma natural hasta que baje el pasador. Tardará aprox. 10 minutos en bajar el pasador.","Mientras el jamón se cocina al vapor en su Instant Pot, precaliente el horno a 375 grados F. Luego agregue TODOS los ingredientes del glaseado en un tazón pequeño para mezclar y bata para combinar. Reserve.","Pase el asado a una tabla de cortar y use un cuchillo afilado para marcar el jamón. Comience por un extremo y haga cortes de aprox. 1/4-1/3 de pulgada de profundidad y a aprox. 1 pulgada de distancia. Luego gire el jamón y repita en diagonal de un lado al otro. (Vea las fotos del proceso arriba para una referencia visual.)","Coloque el jamón marcado en un recipiente apto para horno y vierta el glaseado de arce encima, usando una brocha de silicona para asegurarse de que la superficie del jamón quede completamente cubierta con el glaseado.","Hornee sin tapar de 15 a 20 minutos, untando el glaseado cada pocos minutos. Luego, opcionalmente, puede gratinar el jamón de 2 a 3 minutos para dorar ligeramente la parte superior, pero puede omitir este paso si lo prefiere.","Retire del horno y deje reposar de 5 a 10 minutos. Luego use un cuchillo dentado o un cuchillo eléctrico para cortar en rebanadas. Sirva y disfrute."],
["¡No se intimide! Es MUCHO más fácil de hacer de lo que parece. 🙂 Asegúrese de usar un caldo de buena calidad y muy sabroso para obtener los mejores resultados. Yo uso y me encanta este caldo casero, pero el comprado en tienda también funciona. La gasa de queso es más fácil que el papel pergamino y el papel de aluminio para envolver su jamón vegano. Además, es segura para alimentos si prefiere evitar el aluminio. Dé al jamón un poco de tiempo de reposo antes de cortarlo. A medida que comienza a enfriarse, se firma más, lo que facilita el corte y permite obtener rebanadas más delgadas. Las sobras se conservan refrigeradas en un recipiente sellado hasta por 5 días. Puede congelar las sobras, enteras o en rebanadas, en una bolsa con cierre o en un recipiente apto para congelador hasta por 3 meses."],[]))
X.append(r(9661912,"Ensalada de col rizada (kale) con naranja y vinagreta cítrica","Esta ensalada de col rizada (kale) con naranja, también conocida como ensalada invernal de kale, es fresca y cítrica, con toques de dulzor y acidez en cada bocado. Rica en sabor, pero requiere solo unos pocos ingredientes. ¡Lista en 20 minutos!","4 porciones","1 porción",
[("Para la ensalada","6 tazas compactas de col rizada (kale), aprox. 1 manojo grande, sin los tallos gruesos y con la col rizada partida en trozos grandes del tamaño de un bocado"),("Para la ensalada","2-3 cucharadas de jugo de limón, aprox. medio limón grande"),("Para la ensalada","1 lata de 15 onzas de garbanzos, escurridos y enjuagados"),("Para la ensalada","¼ de taza de semillas de cáñamo peladas, semillas de calabaza (pepitas) crudas o semillas de girasol"),("Para la ensalada","1 naranja pelada y en gajos"),("Para la vinagreta cítrica","⅓ de taza de jugo de naranja recién exprimido, aprox. 1 naranja mediana"),("Para la vinagreta cítrica","2 cucharadas de vinagre de manzana"),("Para la vinagreta cítrica","1 cucharadita de mostaza amarilla"),("Para la vinagreta cítrica","1 cucharadita de jengibre molido"),("Para la vinagreta cítrica","¼ de cucharadita de sal marina")],
["Parta la col rizada en trozos grandes del tamaño de un bocado, retire los tallos gruesos y deséchelos. Enjuague bien y luego agregue a un tazón grande para mezclar. Vierta el jugo de limón encima y masajee la col rizada con las manos durante 2-3 minutos. Esto marchitará y ablandará suavemente la col rizada.","Agregue los garbanzos y las semillas de cáñamo al mismo tazón y reserve.","Combine los ingredientes del aderezo en un tazón pequeño y bata bien para combinar. Luego vierta el aderezo sobre la ensalada y mezcle bien para distribuir de manera uniforme.","Decore con los gajos de naranja y disfrute."],
["Asegúrese de masajear la col rizada. No omita este paso. Solo toma 2-3 minutos y los resultados valen la pena. Use jugo de naranja recién exprimido para obtener el mejor sabor. Si no tiene vinagre de manzana, sustitúyalo por vinagre de vino blanco o vinagre balsámico blanco con resultados similares. Las sobras se conservan refrigeradas de 1 a 2 días."],[]))
X.append(r(9665970,"Calabaza bellota en freidora de aire","Esta calabaza bellota en freidora de aire requiere solo 4 ingredientes, pero está cargada de sabor y no decepcionará.","3 porciones","1 porción",
["2 libras de calabaza bellota (1 calabaza pequeña), pelada + cortada en cubos de media pulgada","2 cucharadas de caldo de verduras bajo en sodio","½ cucharadita de sal marina","½ cucharadita de pimentón ahumado","½ cucharadita de ajo en polvo"],
["Pele y corte la calabaza bellota en cubos de media pulgada y colóquelos en un tazón para mezclar.","Agregue los demás ingredientes al tazón y mezcle bien para distribuir el condimento de manera uniforme.","Programe la freidora a 400°F/200°C y cocine la calabaza bellota en la freidora de aire de 18 a 24 minutos, mezclando o sacudiendo ocasionalmente. El tiempo de cocción variará entre los distintos modelos de freidora."],
["Tenga cuidado al cortar y pelar la calabaza, ya que tiene una cáscara muy dura. Cada freidora de aire variará en los tiempos de cocción, así que asegúrese de que la calabaza esté tierna al pincharla con un tenedor y con los bordes crujientes antes de servir. Las sobras se conservan en un recipiente sellado en el refrigerador de 3 a 4 días."],[]))
X.append(r(9666805,"Puré vegano de polenta","Puré cremoso de polenta, sabroso y delicioso, con menos calorías que el puré de papas.","4 porciones","1 porción",
["2 cucharadas de mantequilla vegana (o aceite de cocina (para una versión sin aceite, omita y saltee con caldo))","2-3 dientes de ajo (picados finamente)","4 tazas de caldo de verduras","1 taza de harina de maíz","1 taza de leche de avena sin azúcar (o la leche no láctea de su elección)","1/4 de taza de queso parmesano vegano (opcional, pero recomendado)","mantequilla vegana o aceite de oliva","cebollino, cebollín o eneldo recién picado","salsa gravy de cebolla","salsa gravy de miso"],
["Derrita la mantequilla (si la usa) y saltee el ajo de 30 a 60 segundos hasta que esté aromático.","Agregue el caldo y lleve a ebullición. Luego baje el fuego y vierta lentamente la harina de maíz. Cocine a fuego bajo, revolviendo con frecuencia de 15 a 20 minutos, hasta que esté muy espesa y tierna.","Apague el fuego, agregue la leche y el queso parmesano vegano, y mezcle bien. Sirva de inmediato."],[],[]))
save(5,X)
